import React from 'react';
import { Box } from '@salesforce/retail-react-app/app/components/shared/ui';
import type { BoxProps } from '@chakra-ui/layout';

type BoxedProp = boolean | 'desktop';

type PageContainerProps = BoxProps & {
  /**
   * Controls horizontal containment:
   *   true       — constrained (maxWidth + padding) on all breakpoints
   *   "desktop"  — full-width on mobile, constrained from lg upward
   *   false      — full-width everywhere (default)
   */
  boxed?: BoxedProp;
};

const PageContainer = ({ boxed, children, ...rest }: PageContainerProps) => {
  const maxWidthValue = !boxed
    ? undefined
    : boxed === 'desktop'
    ? { base: '100%', lg: 'container.xxxl' }
    : 'container.xxxl';

  const paddingXValue = !boxed ? undefined : boxed === 'desktop' ? { base: 0, lg: 6, xl: 8 } : [4, 4, 6, 6, 8];

  return (
    <Box width="100%" maxWidth={maxWidthValue} marginX={boxed ? 'auto' : undefined} paddingX={paddingXValue} {...rest}>
      {children}
    </Box>
  );
};

export default PageContainer;

